INSERT INTO listing (id,title,description,price_chf,condition,category,postcode,locality,created_at) VALUES
    (1,'Speziell 3 Gang Damenvelo 28 Zoll, Oldtimer,','Ich verkaufe hier ein 3 Gang Damen Fahrrad Speziell construcción. Die Fahrrad ist gebraucht aber in sehr guten Zustand, alles funktioniert. Speziell Funktion das Tretlager muss drehen in die andere Richtung als normales Fahrrad, (siehe 3 Bild). Modell: Oldtimer Marke: ???? Schaltung: Sturmey Archer, 3 -Gang Kurbel: (46 Zahn) Bremsen: Weismann, Duralca. Felgen: Alu. Pneu Vorne und Hinten noch in Guten Zustands, Grösse: ca. 48/53- Körpergrösse ca. 180-190cm. Rahmengrössen: Lenkstange bis Sattel ca. 550 mm / Sattel bis Kurbel ca. 560 mm / Kurbel bis Gabel ca. 650 mm ; von Boden bis Sattel ca. 85 cm, von Pedal bis Sattel ca. 75 cm . Rahmen: Stahl mit Kratzer. Farbe: Grun. Gewicht: ca. 15.150 kg. Zubehör: Schutzblech vorne und hinten. Seitenstütze, Gepäckträger. Dieses Fahrrad ist in einem Superzustand und sofort fahrbereit - es wartet nur noch auf Sie :-) - 28 Zoll. - Abholen in 2533 Evilard, BE (moglich auch Versand). Sie können einen Termin vereinbaren und den Artikel abholen, oder ich sende Ihnen den Artikel per Post (B), 30.-- Fr, dann fallen die Versandkosten zu Ihren Lasten. Bei Abholung können Sie bar bezahlen. Bei Lieferung bitte im voraus bezahlen. Ebanking ist kostenlos, habe IBAN und Twint. Sofort nach Geldeingang wird die Ware verschickt.',120,'LIKE_NEW','bikes','2533','Leubringen','2026-10-09T11:29:15Z'),
    (2,'Koor Ruuky 12','Super leichtes Fahrrad in top Zustand! Kann auch in Sursee abgeholt werden. Bei Interesse melden. Internet-Details: Gewicht: 3,4 kg (Rahmen und Gabel bestehen vollständig aus leichtem Aluminium, was Eltern das Tragen und Kindern das Lenken erleichtert). Alters- & Grössenempfehlung: Ideal ausgelegt für Kinder von 1,5 bis 3 Jahren (ab ca. 18 Monaten) bzw. eine Körpergrösse zwischen 80 und 100 cm. Sitzhöhe: Der ergonomische Kindersattel ist von 37 bis 51 cm stufenlos höhenverstellbar und wächst somit mit dem Kind mit. Bereifung: 12-Zoll-Luftreifen, die im Vergleich zu Hartplastik- oder Schaumreifen bodenschonend wirken und Stösse auf Asphalt oder Spielplätzen dämpfen. Lenkung: Ausgestattet mit einem hochwertigen Neco-Steuersatz, wie er auch bei Fahrrädern für Erwachsene verbaut wird. Dies sorgt für ein stabiles, spielfreies und präzises Lenkverhalten. Bremssystem: Dieses Modell besitzt keine Bremse, da in dieser Altersklasse primär das Bremsen mit den Füssen auf dem Boden erlernt wird.',80,'USED','bikes','5102','Rupperswil','2026-09-30T04:11:28Z'),
    (3,'14" BTWN 2in1 Fahrrad/laufrad','Dein Kind lernt zunächst auf dem Laufrad, das Gleichgewicht zu halten und ist anschliessend mit den in 10 Sekunden montierten Pedalen auf dem Velo unterwegs!',70,'USED','bikes','8505','Pfyn','2026-10-23T13:52:05Z'),
    (4,'Merida Reacto 6000 (M)','Merkmale Merida Reacto 6000 Das Reacto 6000 ist ein Fahrrad, das von der Radsportpresse hoch gelobt wurde. Die präzise Schaltung und die tadellose Bremsleistung der Shimano 105 Di2 Gruppe lassen sich perfekt mit der Renngeometrie des leichten CF3 Carbonrahmens kombinieren. Das Merida Reacto 6000 ist ein High-Performance-Rennrad mit einem Reacto CF3 IV Carbonrahmen. Dieser leichte und aerodynamische Rahmen wurde entwickelt, um eine effiziente und schnelle Fahrt zu bieten. Es kommt mit einer Shimano 105 Di2 Schaltgruppe und Vision SC 60 Carbonfelgen. Seine herausragende aerodynamische Performance, das geringe Gewicht, das präzise Handling und die blitzschnelle Beschleunigung machen es zum perfekten Rad für Kriterien und Sprinter. Gleichzeitig ermöglicht es ihm sein klassenführender Komfort, seinen aerodynamischen Vorteil auch auf Kopfsteinpflaster oder auf den idyllischen, aber holprigen Straßen Ihrer Lieblingstrainingsstrecke zu nutzen. Rahmen: Reacto CF3 IV Carbon; max. 700x30C Radgröße 100x12/ 142x12mm Achse Standard BB86,5 Innenlager Standard Gabel: Reacto CF3 IV Carbon, Material: Carbon 700x30C max. Radgröße Schaltung: Shimano 105 Di2. Umwerfer: Shimano 105 Di2 Hebel: Shimano 105 Disc Di2 Kurbeln: Shimano 105 R7100 52-36T. Kassette: Shimano 105 R7101 11-34T 12-fach. Bremsen Bremsen: Shimano 105 Disc Scheiben: 160 mm Räder und Reifen Felgen: Vision SC 60 I23 Carbon-Scheibenbremse. Reifen: Continental Grand Prix TR 700x28C faltbar und Tubeless Ready Weitere Komponenten Lenker: Merida Expert CW Aluminium. Vorbau: Merida Expert SL 2P II Aluminium. Sattelstütze: Merida Team CW Carbon. Sattel: Merida Expert SL. Ungefähres Gewicht: 8,7 kg (Größe M)',2500,'USED','bikes','6003','Luzern','2026-10-20T08:10:55Z'),
    (5,'Trek Mountainbike Fully Fahrrad Velo Jugend ab Service','Trek-Fully-Mountainbike (vollgefedert) Hochwertiges, vollgefedertes Mountainbike der Qualitätsmarke Trek. Ideal geeignet für Jugendliche oder kleinere Erwachsene, die ein verlässliches Bike für Geländefahrten, Trails oder den Alltag suchen. Marke: Trek Laufradgröße: 26 Zoll Federung: Fully (Federgabel vorne & Dämpfer hinten für optimalen Komfort im Gelände) Bremssystem: Scheibenbremsen vorne und hinten Ausstattung: Hochwertige Komponenten Zustand: Gebraucht und sofort einsatzbereit Bei Interesse oder Fragen einfach melden! Besichtigung und Probefahrt nach Absprache gerne in 8580 Amriswil möglich. Ich habe weitere Fahrräder im Angebot. ICH AKZEPTIERE IHR ALTES FAHRRAD ALS EINE KLEINE ANZHLUNG.',450,'GOOD','bikes','8580','Amriswil','2026-10-21T02:39:48Z'),
    (6,'Mountainbike Scott Jugend Velo Fahrrad ab Service','Scott-Mountainbike für Jungen. Das Velo hat einen Aluminiumrahmen und eine Hardtail-Federung. Es ist gebraucht und befindet sich in einem guten Zustand mit üblichen Gebrauchsspuren. Das Fahrrad ist voll funktionsfähig und sofort einsatzbereit. Alle Komponenten entsprechen den Bildern. Ein solides Modell für den Alltag oder Ausflüge. Besichtigung vor Ort in 8580 Amriswil ist nach Absprache möglich. Versand ist mit der Post möglich. Ich nehme auch Ihr altes Fahrrad als Anzahlung.',380,'GOOD','bikes','8580','Amriswil','2026-10-03T15:37:21Z'),
    (7,'Gepäckträgerbox, Topcase, Box (abschliessbar, Top Zustand)','Abzugeben, weil doch nicht montiert. Sehr guter Zustand, inklusive Befestigungsmaterial und zwei Schlüsseln. Für Velo, e-Bike, Scooter, Mofa, e-Scooter, Fahrrad, Trotti, Roller und Co. Marke: Polisport Grösse, circa: - 40 cm lang - 25 cm breit - 15 cm hoch Farbe: schwarz Ansehen, Abholung, Übergabe möglich. Versand auch, gegen Aufpreis.',23,'USED','bikes','4054','Basel','2026-10-12T16:40:51Z'),
    (8,'Damen Fahrrad','Das Fahrrad ist in einem super Zustand, alles funktioniert einwandfrei. Schaltung und Bremsen funktionieren perfekt. Das Vorderlicht funktioniert. 26 zoll. Es hat eine eigene Pumpe.',60,'USED','bikes','8051','Zürich','2026-09-28T20:00:46Z'),
    (9,'Koor Kinderfahrrad,Fahrrad, Velo, neuwertig, dicke Reifen','Frisches Kinderfahrrad in Alufelgenoptik! Dieses robuste Velo mit 20-Zoll-Rädern ist ideal für kleine Abenteurer. Das Fahrrad ist in einem sehr guten Zustand, wurde wenig benutzt und ist wie neu. Mit seinem leichten Aluminiumrahmen und den breiten Reifen bietet es Stabilität und Fahrspaß. Ideal für Kinder, die die Welt auf zwei Rädern entdecken wollen. Ein tolles Angebot für preisbewusste Eltern. Jetzt zugreifen und dem Nachwuchs eine Freude machen! Ich habe weitere Fahrräder im Angebot. Der Versand erfolgt per Post. Besichtigung und Probefahrt sind in 8580 Amriswil möglich. ICH AKZEPTIERE IHR ALTES FAHRRAD ALS ZAHLUNGSMITTE',250,'LIKE_NEW','bikes','8580','Amriswil','2026-10-13T12:31:27Z'),
    (10,'Kinderfahrrad Bulls schwarz gelb 24 Zoll ab Service','Dieses Mountainbike der Marke Bulls ist für Kinder konzipiert. Der Rahmen besteht aus Aluminium und hat eine Größe von 32 cm. Es handelt sich um ein Hardtail-Modell. Das Velo ist voll funktionsfähig und weist normale Gebrauchsspuren auf. Ein Gepäckträger sowie Schutzbleche und Dynamolicht sind montiert. Die Details sind den Bildern zu entnehmen. Das Velo ist für den täglichen Gebrauch gut geeignet. Besichtigung in Amriswil; ich habe weitere Fahrräder im Angebot und akzeptiere Ihr altes Fahrrad als Anzahlung. Versand erfolgt mit der Post.',220,'GOOD','bikes','8580','Amriswil','2026-09-26T14:45:02Z'),
    (11,'Militärvelo von 1939 in Originalzustand','Das seltene Sammlerstück mit der Nummer 17069 hat einen originale Patina. Verkaufe mein gut gehütetes Militärrad an einen Sammler oder Freund historischer Fahrräder. Alle Teile sind von 1939 gestempelt. Ideal als Geschenk für besondere Verdineste oder für eine Sammlung. I weiss dä Gang cha nid jede trampe, wenns rollt schaffsch au chlini Rampe Wötsch das es richtig abgot derno, chasch es zu E-Bike umbaue lo? Der Preis steht für Rarität nicht wahr, ist nicht verhandelbar wie bei einem Basar. Es kann gerne besichtigt und Probegefahren und gegen Barzahlung/Twint gleich mitgenommen werden. Zudem stehen weitere Ordonanzräder zum Verkauf bereit. Freue mich auf deine Kontaktaufnahme :-)',939,'USED','bikes','4153','Reinach BL','2026-10-13T13:21:11Z'),
    (12,'Racer Team_Pro-HT 26"','Vendo bicicletta Racer Team-Pro HT causa inutilizzo. In buonissimo stato con normali segni d''usura. Nel 2025 sono stati sostituiti: - i Freni con dei Magura MT5, - la Forcella con una SuntourRaidon xc rl-r 120mm, - il Reggisella con uno SuntourSP12NCX 12 Fr 450.- Da ritirare a Locarno Eventuali spese di spedizione da concordare. Vélo Racer Team_Pro HT Je vends un vélo Racer Team-Pro HT, faute d''utilisation. En très bon état, avec des traces d''usure normales. En 2025, les éléments suivants ont été remplacés : - les freins, par des Magura MT5, - la fourche, par une Suntour Raidon XC RL-R 120 mm, - la tige de selle, par une Suntour SP12 NCX 12. 450 CHF à retirer à Locarno. Frais d''expédition éventuels à convenir. Fahrrad Racer Team_Pro HT Ich verkaufe mein Fahrrad Racer Team-Pro HT, da es nicht mehr benutzt wird. Es befindet sich in sehr gutem Zustand und weist normale Gebrauchsspuren auf. Im Jahr 2025 wurden folgende Teile ausgetauscht: - Bremsen: Magura MT5 - Federgabel: Suntour Raidon XC RL-R 120 mm - Sattelstütze: Suntour SP12 NCX 12 450 CHF Abzuholen in Locarno. Eventuelle Versandkosten nach Absprache.',450,'USED','bikes','6600','Locarno','2026-10-04T06:15:15Z'),
    (13,'Fahrrad','Verkaufe mein Fahrad wegen nicht gebrauch. Das Fahrrad fährt sich einwandfrei. Pneu vorne und hinten Neu bremsen funktionieren zahnkranz neu.Habe vor einem Jahr noch einen Service gemacht.',200,'LIKE_NEW','bikes','9050','Appenzell','2026-10-08T01:49:48Z'),
    (14,'Kindervelo Cube 24 Zoll','Velo Kindervelo Fahrrad MTB Cube 24 Zoll orange blau Scheibenbremsen Im Frühling gekauft, im Sommer viel genutzt, war am 21.10.26 frisch im Service, Pedalen ersetzt Voll funktionsfähig, ein paar Kratzer am Lenker',350,'USED','bikes','9014','St. Gallen','2026-09-24T03:51:54Z'),
    (15,'Herren e-Bike','Guten Tag Ich gebe ein elektro-Fahrrad ab, Hersteller EGOMOVEMENT , Model Skarabäus. Fahrrad wird bis 25 Km/h unterstützt. Die Rahmenhöhe beträgt 54 Zentimeter , für Personen ab 1.75m bis 1.85m. Raddimension 28 Zoll, (700x420) 42-622 Kenda Reifen mit Reflektoren, sind im Neuzustand. Motor hat 250W / 36V. Batterie 250W Das Fahrrad wiegt nur 18.5 Kilo und ist im vergelich zu andeten e-Bikes noch recht leicht. Es hat 10 Gänge und 5 verschiedene Fahrstufen. Schutzblech hinten mit integriertem Rücklicht. Seitenständer, Gepäckträger und Schutzblech sind vorhanden. Die Pedalen haben eine antirutschoberfläche und haben zudem noch Rückstrahler. An der Gabel sind Aufnahmen vorhanden, so das man dort auch ein Lowrider Gepäckträger für Taschen nachrüsten könnte bei Bedarf. Die Bremsen sind hydraulisch mir Mineraloil. Scheibendurchmesser 160mm. Felgen Doppelwandig. Den Sattel kann man per Schnellspanner in kurze Handgriffe verstellen. Farbe metalise schwarz. Das e-Bike hat aktuell ca 10 km und wird inkl Garantie abgegeben. Eine Probefahrt ist nach vorheriger Absprache möglich. Abgabe ohne Tasche. Dafür gibts ein Helm Grösse M, gratis mitdazu. Der Preis ist verhandelbar. Abgabe inklusive Ladegerät. Bei Fragen und Interesse bitte anrufen, oder schreiben Sie mir eine Nachricht via Kontaktformular. Vielen Dank! MfG R.B',990,'LIKE_NEW','bikes','8620','Wetzikon ZH','2026-10-14T19:55:40Z'),
    (16,'E-Bike Hercules schwarz (Fahrrad super, Akku defekt)','- ROBERT/A E-Bike von HERCULES inkl. neuem Körbli - Fahrrad ist in gutem Zustand und alles funktioniert wunderbar, nur der Akku muss ersetzt werden: BOSCH 0 275 007 531 / 72027 0621 3 / 36V / 13.4 AH 500Wh (ca. CHF 300 - 750)',90,'LIKE_NEW','bikes','8002','Zürich','2026-10-06T05:07:50Z'),
    (17,'Kindervelo Starlite 16 Zoll neu','Kindervelo Starlite 16 Zoll neu. Wir kauften das Fahrrad zu früh brauchen es aber nicht, da wir diese Grösse direkt überspringen.',100,'LIKE_NEW','bikes','3186','Düdingen','2026-09-25T07:00:20Z'),
    (18,'Thule Thru-Axle Adapter / Steckachse Syntace M12 × 1.0','Verkaufe einen gebrauchten Thule Thru-Axle Adapter für die Befestigung eines Thule Fahrradanhängers / Chariots an Fahrrädern mit Syntace-Steckachse. Details: * 12 × 148 mm * Achslänge: 160172 mm * Gewinde: M12 × 1.0 * Syntace * Thule Art.-Nr. 20110733 * inkl. Originalverpackung * guter gebrauchter Zustand Passend für verschiedene Thule Fahrradanhänger wie Chariot Cross, Sport, Lite, Cab, Coaster etc. Abholung oder Versand gegen Aufpreis möglich.',40,'USED','bikes','5430','Wettingen','2026-09-26T10:53:48Z'),
    (19,'Thule Syntace X-12 Steckachsen-Adapter M12x1.0 20100765','Verkaufe einen originalen Thule Syntace X-12 Axle Adapter für die Befestigung eines Thule Fahrrad-/Kinderanhängers. * Modell: 20100765 * Für Syntace X-12 Steckachs-System * Durchmesser: 12 mm * Gewinde: M12 x 1.0 * Achslänge: 160 mm * Gesamtlänge: 180 mm * Passend für verschiedene Thule Chariot Modelle * Gebraucht, guter Zustand * Inkl. Originalverpackung Abholung oder Versand nach Absprache möglich.',40,'USED','bikes','5430','Wettingen','2026-09-28T13:43:04Z'),
    (20,'Thule Shimano E-Thru Steckachse / Adapter 12 mm 20100766','Original Thule Shimano E-Thru Axle Adapter für die Befestigung eines Thule Kinder-/Veloanhängers an Fahrrädern mit 12-mm-Shimano-Steckachse. * Marke: Thule * Modell / Art.-Nr.: 20100766 * Shimano E-Thru * Gewinde: M12 × 1,5 * Achslänge: ca. 170 mm * Inkl. Originalverpackung * Gebraucht, guter Zustand und voll funktionsfähig Abholung oder Versand gegen Porto möglich.',40,'USED','bikes','5430','Wettingen','2026-10-21T21:59:08Z'),
    (21,'Mountain bike','Ich verkaufe ein Scott Mountainbike mit Vollfederung. Das Fahrrad befindet sich in einem guten technischen und optischen Zustand. Ideal für Waldwege, Bergtrails sowie für gemütliche Fahrten im Gelände. Das Bike verfügt über eine gefederte Vorder- und Hinterradaufhängung, was hohen Fahrkomfort und gute Kontrolle auf unebenem Untergrund bietet. Die Scheibenbremsen funktionieren zuverlässig. Laufräder mit DT Swiss-Felgen, Schwalbe-Reifen in sehr gutem Zustand. Das Fahrrad ist mit einem Luftsattel ausgestattet, der den Fahrkomfort deutlich erhöht, besonders auf längeren Strecken. Ehrliche Information: Eine Schaltung benötigt eine Einstellung oder einen Service. Beim Gangwechsel ist das Schalten nicht immer ganz sauber, gelegentlich hakt es, die Schaltung funktioniert jedoch und die Gänge lassen sich wechseln. Es handelt sich nicht um einen Totalausfall, eher um eine Frage der Justierung oder einer kleinen Reparatur. Der Rahmen ist gerade, ohne Risse oder versteckte Mängel. Das Fahrrad ist fahrbereit, abgesehen von der erwähnten Schaltungseinstellung.',650,'USED','bikes','5018','Erlinsbach','2026-09-27T22:48:58Z'),
    (22,'Velo 26"','Kindervelo 26Zoll 21 Gang # Fahrrad # Kinderfahrrad',150,'USED','bikes','8587','Oberaach','2026-10-17T08:02:59Z'),
    (23,'Fahrradständer','Neuer veloständer für 6 Fahrräder outdoor schwere Ausführung Feuerverzinkt für Langlebigkeit vom markenhersteller',570,'LIKE_NEW','bikes','8580','Amriswil','2026-10-17T05:19:43Z'),
    (24,'Crosswave Speedy 20 Zoll Kinderfahrrad Türkis','Verkaufe ein türkisfarbenes Crosswave Speedy Kinderfahrrad mit sportlichem Design. Details: * Marke: Crosswave * Modell: Speedy 20 * Radgrösse: 20 Zoll * Baujahr: 2023 * Farbe: Türkis / Schwarz * Mit Federgabel vorne * Mit Seitenständer und Schutzblech hinten * Sportliche Reifen mit gutem Profil Das Fahrrad weist normale Gebrauchsspuren auf und eignet sich ideal für Kinder, die gerne mit dem Velo unterwegs sind. Es wurde nur von einem Kind gefahren. Besichtigung nach Absprache möglich.',150,'USED','bikes','5015','Erlinsbach SO','2026-10-20T13:41:48Z'),
    (25,'Kinderfahrrad 24 Zoll','Leicht, robust, flexibel anpassbar und mit genialem Handling. Die Basis bildet ein leichter Aluminiumrahmen samt Aluminiumgabel, weil ein Bike, das wenig wiegt, einfach viel mehr Spaß macht! Die Bedienelemente, wie Lenker und Bremshebel, wurden speziell auf kleine Hände abgestimmt, damit die Kids stets die volle Kontrolle behalten. Zahlreiche hochwertige, robuste Komponenten, darunter ein Thun Tretlager (made in Germany), Schwalbe Reifen und eine 8-fach Schaltung, ergänzen das Set-up. Als i-Tüpfelchen gibts ein Zubehör-Komplettset mit Gepäckträger, Schutzblechen, Lichtanlage und Seitenständer. Aufsitzen, antreten und ab geht''s ins Abenteuer! Damaliger Neupreiss 550 Fr. Jetzt in gutem gebrauchten Zustand nur noch 160 Fr. Das Fahrrad wird vor dem Verkauf noch gründlich geprüft und greinigt!',160,'LIKE_NEW','bikes','6014','Luzern','2026-10-22T03:25:00Z'),
    (26,'Fahrrad Marke Peugeot','Guter Zustand.',80,'USED','bikes','3400','Burgdorf','2026-10-13T06:24:22Z'),
    (27,'Velo Fahrrad Crosswave 24 Zoll','Kinder Velo Crosswave 24 Zoll 3x8 Gang Guten Zustand',60,'USED','bikes','3072','Ostermundigen','2026-10-01T21:49:24Z'),
    (28,'Fahrrad und Skihelm','Gut erhaltene Fahrrad und Ski',5,'USED','bikes','3315','Bätterkinden','2026-09-29T05:02:01Z'),
    (29,'Cervélo P5 Force AXS Power Grösse 54 Twilight','Cervélo P5 Force AXS Power Grösse 54 Twilight Ich verkaufe mein Cervélo P5, ein hochwertiges Triathlon-/Zeitfahrrad in sehr gutem Zustand. Das P5 ist extrem aerodynamisch, schnell und steif und eignet sich perfekt für Triathlon, Ironman und Zeitfahren. Das Fahrrad wurde stets sorgfältig behandelt und befindet sich in einem wirklich hervorragenden Zustand. Details: - Modell: Cervélo P5 Force eTap AXS 1 Power - Modelljahr: 2024 - Rahmengrösse: 54 - Farbe: Twilight - Elektronische SRAM Force eTap AXS Schaltung - Integrierter Powermeter Rahmengrösse 54: je nach Körperproportionen und gewünschter Sitzposition ungefähr für eine Körpergrösse von 170180 cm geeignet. Bei einem Triathlonrad empfehle ich grundsätzlich ein professionelles Bike-Fitting. Zusätzlich dabei: - LOOK Keo Blade Carbon Pedale - XLAB Torpedo Versa Slim Trinksystem - Selle Italia WATT Kit Carbonio Superflow Sattel Das Fahrrad wurde bei Tempo Sport professionell aufgebaut, angepasst und mit einem Bike-Fitting eingestellt. Der ursprüngliche Kaufpreis inklusive Ausstattung lag bei über CHF 11''700.. Ich verkaufe das Fahrrad lediglich, weil ich es nicht mehr so oft benutze, wie es dieses Bike verdient hätte. Besichtigung nach Absprache möglich. Bei Interesse oder Fragen gerne melden. Weitere Informationen kann ich selbstverständlich zur Verfügung stellen.',6500,'USED','bikes','8002','Zürich','2026-10-12T19:54:40Z'),
    (30,'Specialized Mountainbike FSR XC','Specialized Mountainbike FSR XC Sehr guter Zustand, wie neu Wenig gefahren und Sehr gepflegt Fully-Mountainbike mit 26 Zoll Neupreis: CHF 2700.00 Abholung vor Ort oder je nachdem persönliches Überbringen möglich Technische Informationen: Rahmenmaterial: Hochwertiges, konifiziertes A1 Premium Aluminium mit Specializeds patentiertem ORE-Design (Optimized Radius Engineering) an Ober- und Unterrohr für maximale Stabilität bei geringem Gewicht. Hinterbau-System: Legendäre FSR-Kinematik (Viergelenker mit Horst-Link), die dafür sorgt, dass die Federung auch beim Bremsen und Pedalieren voll aktiv bleibt. Federweg: In der Regel 100 mm Federweg an Front und Heck (ausgelegt für klassischen Cross-Country- und Trail-Einsatz). Dämpfer (Heck): Luftfederdämpfer mit einstellbarer Zugstufe (oft von Herstellern wie Fox oder X-Fusion). Federgabel: Eine RockShox-Federgabel (je nach exakter Modellvariante oft eine RockShox Duke, Recon oder Tora) mit einstellbarer Vorspannung und Rebound. Antrieb & Komponenten Schaltung: Typischerweise eine 3x9-Gang-Kettenschaltung (27 Gänge). Ab Werk wurden hier meist zuverlässige Shimano Deore, Deore LX oder XT-Komponenten verbaut. Bremsen: Das Velo ist mit hydraulischen Scheibenbremsen ausgestattet (häufig Shimano, Avid oder Hayes), die für konstante Bremskraft bei jedem Wetter sorgen. Laufräder & Reifen: 26 Zoll Laufräder (z.B. mit Mavic- oder Specialized-Felgen). Besonderheiten an diesem spezifischen Velo Auf dem Foto sind ein paar nachträgliche Anpassungen und Zubehörteile zu erkennen: Komfort-Sattelbezug: Auf dem Sattel wurde ein gepolsterter Bezug (Modell von B''TWIN) angebracht. Lenkerhörnchen (Bar Ends): Für zusätzliche Griffpositionen bei längeren Fahrten oder Bergaufpassagen. Schutzblech-Halterung: Am Unterrohr befindet sich ein Clip für ein steckbares Mountainbike-Schutzblech. Händler-Aufkleber: Das Fahrrad wurde ursprünglich über den Schweizer Händler Schmid-Velsport.ch erworben.',400,'LIKE_NEW','bikes','5503','Schafisheim','2026-10-05T08:32:29Z'),
    (31,'BLAZE Kinder-Mountainbike 20 Zoll, 6-Gang, gepflegt','BLAZE Kinder-Mountainbike 20 Zoll, sportlich und gepflegt Verkaufspreis: CHF 139. Verhandlungsbasis (VB) Zum Verkauf steht ein schönes und sportliches Kinder-Mountainbike der Marke BLAZE in auffälligem Rot mit schwarzem Design. Das Fahrrad befindet sich in einem gepflegten gebrauchten Zustand und überzeugt durch seine robuste Bauweise und die sportliche Optik. Ideal für Kinder, die gerne Fahrrad fahren, sei es auf dem Schulweg, bei Freizeitaktivitäten oder bei Ausflügen mit der Familie. Ausstattung und Highlights: * Marke: BLAZE * Radgrösse: 20 Zoll * 6-Gang-Schaltung * Federgabel vorne * Vorder- und Hinterradbremse * Robuster und sportlicher Rahmen * Geländereifen mit gutem Profil * Bequemer Sportsattel * Praktischer Seitenständer * Reflektoren an beiden Rädern Zustand: Das Mountainbike ist optisch gepflegt und weist die üblichen altersbedingten Gebrauchsspuren auf. Der Zustand ist auf den Originalfotos gut ersichtlich. Preis: CHF 139. Verhandlungsbasis Besichtigung und Abholung nach Vereinbarung möglich. Bei ernsthaftem Interesse freue ich mich über eine Nachricht',139,'USED','bikes','8590','Romanshorn','2026-10-23T05:49:25Z'),
